// hash_to_bls_field in c-kzg-4844 bytes.c:
void hash_to_bls_field(fr_t *out, const Bytes32 *b) {
    blst_scalar tmp;
    blst_scalar_from_bendian(&tmp, b->bytes);
    blst_fr_from_scalar(out, &tmp);  // modular reduction, no range check
}
// Differs from bytes_to_bls_field which uses blst_scalar_fr_check to validate range

